import {nextDue} from "./planificacion-domain.mjs";
export function queryClients(clients,visits,filters={}){const norm=x=>String(x??"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLocaleLowerCase("es");const query=norm(filters.query);let rows=clients.filter(c=>(filters.archived==="all"||!!c.archived===(filters.archived==="archived"))&&(!query||norm(JSON.stringify(c.data)).includes(query))&&(!filters.locality||c.data.direccion.localidad===filters.locality)&&(!filters.month||nextDue(c.data).slice(0,7)===filters.month)&&(!filters.status||visits.some(v=>v.client_id===c.id&&(filters.status==="assigned"?["planned","proposed","confirmed"].includes(v.status):v.status===filters.status))));rows.sort((a,b)=>{const primary=filters.sort==="due"?nextDue(a.data).localeCompare(nextDue(b.data)):filters.sort==="locality"?a.data.direccion.localidad.localeCompare(b.data.direccion.localidad,"es"):0;return primary||a.data.nombre.localeCompare(b.data.nombre,"es")||a.id.localeCompare(b.id);});const pageSize=[10,25,50].includes(Number(filters.pageSize))?Number(filters.pageSize):25,pages=Math.max(1,Math.ceil(rows.length/pageSize)),page=Math.min(pages,Math.max(1,Number.isInteger(filters.page)?filters.page:1));return{rows:rows.slice((page-1)*pageSize,page*pageSize),total:rows.length,pages,page,pageSize};}
export function createClientDirectory({getState,escape}){const $=s=>document.querySelector(s);let scope,filters={page:1,pageSize:25,archived:"active",sort:"name",query:"",locality:"",month:"",status:""};const defaults=()=>({page:1,pageSize:25,archived:"active",sort:"name",query:"",locality:"",month:"",status:""});function render(query){const state=getState(),newScope=state.clients[0]?.company_id??state.userId;if(scope!==newScope){scope=newScope;filters=defaults();}if(query!==undefined&&query!==filters.query){filters.query=query;filters.page=1;}const result=queryClients(state.clients,state.visits,filters);filters.page=result.page;$("#client-search").value=filters.query;const option=(value,label,chosen)=>`<option value="${escape(value)}" ${value===chosen?"selected":""}>${escape(label)}</option>`;$("#directory-controls").innerHTML=`<div class="grid-form"><label>Localidad<select data-directory-filter="locality">${option("","Todas",filters.locality)}${[...new Set(state.clients.map(c=>c.data.direccion.localidad))].sort((a,b)=>a.localeCompare(b,"es")).map(x=>option(x,x,filters.locality)).join("")}</select></label><label>Mes de próxima revisión<input type="month" data-directory-filter="month" value="${escape(filters.month)}"></label><label>Visita<select data-directory-filter="status">${[["","Todas"],["pool","En bolsa"],["assigned","Asignada"],["completed","Realizada"],["cancelled","Cancelada"]].map(([v,l])=>option(v,l,filters.status)).join("")}</select></label><label>Clientes<select data-directory-filter="archived">${[["active","Activos"],["archived","Archivados"],["all","Todos"]].map(([v,l])=>option(v,l,filters.archived)).join("")}</select></label><label>Orden<select data-directory-filter="sort">${[["name","Nombre"],["due","Próxima revisión"],["locality","Localidad"]].map(([v,l])=>option(v,l,filters.sort)).join("")}</select></label><label>Por página<select data-directory-filter="pageSize">${[10,25,50].map(n=>option(String(n),String(n),String(filters.pageSize))).join("")}</select></label></div><button type="button" data-directory-action="clear">Limpiar filtros</button><p id="directory-count" role="status">${result.total} de ${state.clients.length} clientes · página ${result.page} de ${result.pages}</p>`;$("#client-cards").innerHTML=result.rows.map(c=>`<article class="card"><h3>${escape(c.data.nombre)}</h3><p>${escape(c.data.telefono)} · ${escape(c.data.email)}</p><p>${escape(c.data.direccion.via)}, ${escape(c.data.direccion.pisoPuerta)}<br>${escape(c.data.direccion.codigoPostal)} ${escape(c.data.direccion.localidad)}, ${escape(c.data.direccion.provincia)}</p><p>${escape(c.data.equipo??"Equipo sin registrar")}</p><p>Próxima revisión: ${escape(nextDue(c.data))}${c.archived?' · Archivado':""}</p><details><summary>Intervenciones (${c.data.revisiones.length})</summary>${c.data.revisiones.map(r=>`<p class="review-log">${escape(r.fecha)} · ${escape(r.descripcion)}</p>`).join("")}</details><div class="actions"><button data-action="edit-client" data-id="${c.id}">Editar</button>${!c.archived?`<button data-action="archive" data-id="${c.id}">Archivar</button>`:""}</div></article>`).join("")||'<p class="empty">No hay clientes con estos filtros.</p>';$("#directory-pages").innerHTML=`<div class="actions"><button data-directory-action="previous" ${result.page===1?"disabled":""}>Anterior</button><label>Página<select data-directory-filter="page">${Array.from({length:result.pages},(_,i)=>option(String(i+1),String(i+1),String(result.page))).join("")}</select></label><button data-directory-action="next" ${result.page===result.pages?"disabled":""}>Siguiente</button></div>`;}function change(e){const key=e.target.dataset.directoryFilter;if(!key)return false;filters[key]=["page","pageSize"].includes(key)?Number(e.target.value):e.target.value;if(key!=="page")filters.page=1;render();return true;}function click(e){const action=e.target.closest("[data-directory-action]")?.dataset.directoryAction;if(!action)return false;if(action==="clear")filters=defaults();else filters.page+=action==="next"?1:-1;render();return true;}return{render,change,click};}
